/**
 * Gemini Schema Sanitizer
 *
 * Gemini's function-calling `parameters` accept only a restricted subset of
 * JSON Schema (a slice of OpenAPI 3.0). MCP servers, however, advertise tool
 * input schemas generated by Pydantic / zod / etc., which routinely include
 * keywords Gemini rejects with HTTP 400 — e.g. `propertyNames`,
 * `exclusiveMinimum`, `additionalProperties`, `$schema`.
 *
 * Because every tool is sent in a single `functionDeclarations` array, ONE
 * poisoned schema fails the entire request, taking the whole agent down with
 * "Invalid JSON payload received. Unknown name ..." for every message.
 *
 * This module recursively rewrites a schema into the Gemini-supported subset:
 * unsupported keywords are dropped, and a few are converted to their closest
 * supported equivalent (exclusive bounds → inclusive, `const` → single-value
 * enum, type arrays / `{type:"null"}` union branches → `nullable`).
 */

// Keys Gemini's Schema accepts (camelCase — the @google/genai SDK serializes
// these to the snake_case REST wire format itself).
const ALLOWED_KEYS = new Set([
    'type', 'format', 'title', 'description', 'nullable', 'default', 'enum',
    'items', 'minItems', 'maxItems',
    'properties', 'required', 'minProperties', 'maxProperties', 'propertyOrdering',
    'minimum', 'maximum', 'minLength', 'maxLength', 'pattern',
    'anyOf', 'example',
]);

// Gemini only honors a handful of `format` values; unknown ones (e.g. "uri",
// "email", "uuid") have historically triggered 400s, so drop anything else.
const SAFE_FORMATS = new Set(['enum', 'date-time', 'float', 'double', 'int32', 'int64']);

/**
 * Recursively sanitize a JSON Schema into Gemini's supported subset.
 * Pure: returns a new object and never mutates the input.
 * @param {*} schema - A JSON Schema node (object), or any nested value.
 * @returns {*} A Gemini-safe schema node.
 */
function sanitizeGeminiSchema(schema) {
    if (Array.isArray(schema)) return schema.map(sanitizeGeminiSchema);
    if (!schema || typeof schema !== 'object') return schema;

    const out = {};

    for (const [key, value] of Object.entries(schema)) {
        switch (key) {
            // Unsupported with no safe equivalent — drop.
            case '$schema':
            case '$id':
            case '$ref':
            case '$defs':
            case 'definitions':
            case 'additionalProperties':
            case 'propertyNames':
            case 'patternProperties':
            case 'unevaluatedProperties':
            case 'multipleOf':
            case 'examples':
            case 'not':
            case 'if':
            case 'then':
            case 'else':
            case 'dependentSchemas':
            case 'dependentRequired':
            case 'contains':
                break;

            // Union keywords are normalized to `anyOf` after the loop.
            case 'anyOf':
            case 'oneOf':
            case 'allOf':
                break;

            // Exclusive bounds → closest inclusive equivalent Gemini supports.
            case 'exclusiveMinimum':
                if (typeof value === 'number') out.minimum = value;
                break;
            case 'exclusiveMaximum':
                if (typeof value === 'number') out.maximum = value;
                break;

            // `const` → single-value enum.
            case 'const':
                out.enum = [value];
                break;

            case 'format':
                if (typeof value === 'string' && SAFE_FORMATS.has(value)) out.format = value;
                break;

            case 'type':
                // JSON Schema allows ["string","null"]; Gemini wants a single
                // type plus `nullable`.
                if (Array.isArray(value)) {
                    if (value.includes('null')) out.nullable = true;
                    out.type = value.find(t => t !== 'null') || 'string';
                } else {
                    out.type = value;
                }
                break;

            case 'properties': {
                const props = {};
                for (const [k, v] of Object.entries(value || {})) {
                    props[k] = sanitizeGeminiSchema(v);
                }
                out.properties = props;
                break;
            }

            case 'items':
                out.items = sanitizeGeminiSchema(value);
                break;

            default:
                if (ALLOWED_KEYS.has(key)) out[key] = value;
                // else: silently drop unknown / unsupported keyword.
                break;
        }
    }

    // Normalize unions. Gemini only supports `anyOf` (not oneOf/allOf) and
    // cannot represent a `null` branch — fold that into `nullable` instead.
    const union = schema.anyOf || schema.oneOf || schema.allOf;
    if (Array.isArray(union)) {
        const branches = [];
        for (const branch of union) {
            const isNull = branch
                && (branch.type === 'null'
                    || (Array.isArray(branch.type) && branch.type.every(t => t === 'null')));
            if (isNull) {
                out.nullable = true;
                continue;
            }
            branches.push(sanitizeGeminiSchema(branch));
        }

        if (branches.length === 1) {
            // Collapse a single-branch union (e.g. Pydantic `Optional[X]`) into
            // the parent so we don't emit a pointless one-element anyOf.
            const [only] = branches;
            const nullable = out.nullable;
            Object.assign(out, only);
            if (nullable) out.nullable = true;
            delete out.anyOf;
        } else if (branches.length > 1) {
            out.anyOf = branches;
            // Gemini rejects `type` alongside `anyOf`.
            delete out.type;
        }
    }

    return out;
}

/**
 * Sanitize the `parameters` of a list of Gemini function declarations in place
 * of the originals, returning new declaration objects.
 * @param {Array<{name:string, description?:string, parameters?:object}>} declarations
 * @returns {Array} Declarations with Gemini-safe `parameters`.
 */
function sanitizeFunctionDeclarations(declarations) {
    if (!Array.isArray(declarations)) return declarations;
    return declarations.map(decl => {
        if (!decl || !decl.parameters) return decl;
        return { ...decl, parameters: sanitizeGeminiSchema(decl.parameters) };
    });
}

module.exports = { sanitizeGeminiSchema, sanitizeFunctionDeclarations };
